<?php
declare(strict_types=1);
namespace Zoosper\Auth\Admin\Grid\AccessToken;
use PDO;use Zoosper\Core\Pagination\PaginationResult;use Zoosper\Core\Url\AdminUrlGenerator;use Zoosper\Grid\{GridColumn,GridCriteria,GridDataSourceInterface,GridDefinition,GridFilter};
final readonly class AccessTokenGrid implements GridDataSourceInterface{public const KEY='admin.access-tokens';public function __construct(private PDO $pdo,private int $ownerId,private AdminUrlGenerator $urls,private string $csrf){}public function definition():GridDefinition{return new GridDefinition('Personal Access Tokens',[new GridColumn('name','Name',true),new GridColumn('scopes','Scopes'),new GridColumn('expires_at','Expires',true),new GridColumn('last_used_at','Last used',true),new GridColumn('status','Status'),new GridColumn('actions','Actions',toggleable:false,render:fn(mixed $v,array $r):string=>(($r['revoked_at']??null)!==null?'':'<form method="post" action="'.htmlspecialchars($this->urls->url('access-tokens/'.(int)$r['id'].'/revoke'),ENT_QUOTES,'UTF-8').'"><input type="hidden" name="_csrf_token" value="'.htmlspecialchars($this->csrf,ENT_QUOTES,'UTF-8').'"><button type="submit" class="button button--danger">Revoke</button></form>'))],[new GridFilter('q','Search'),new GridFilter('status','Status','select',[['value'=>'active','label'=>'Active'],['value'=>'expired','label'=>'Expired'],['value'=>'revoked','label'=>'Revoked']])],'created_at','desc','No Personal Access Tokens have been created.');}public function paginate(GridCriteria $c):PaginationResult{$w=['admin_user_id=:owner'];$p=['owner'=>$this->ownerId];$q=trim((string)($c->filters['q']??''));if($q!==''){$w[]='name LIKE :q';$p['q']='%'.$q.'%';}$status=(string)($c->filters['status']??'');$now=gmdate('Y-m-d H:i:s');if($status==='revoked')$w[]='revoked_at IS NOT NULL';elseif($status==='expired'){$w[]='revoked_at IS NULL';$w[]='expires_at IS NOT NULL AND expires_at<=:now';$p['now']=$now;}elseif($status==='active'){$w[]='revoked_at IS NULL';$w[]='(expires_at IS NULL OR expires_at>:now)';$p['now']=$now;}$base=' FROM personal_access_tokens WHERE '.implode(' AND ',$w);$n=$this->pdo->prepare('SELECT COUNT(*)'.$base);$n->execute($p);$sort=['name'=>'name','expires_at'=>'expires_at','last_used_at'=>'last_used_at','created_at'=>'created_at'][$c->sortBy??'created_at']??'created_at';$dir=$c->sortDir==='asc'?'ASC':'DESC';$s=$this->pdo->prepare('SELECT id,name,scopes_json AS scopes,expires_at,last_used_at,revoked_at,created_at,CASE WHEN revoked_at IS NOT NULL THEN \'Revoked\' WHEN expires_at IS NOT NULL AND expires_at<=:status_now THEN \'Expired\' ELSE \'Active\' END AS status'.$base." ORDER BY $sort $dir,id $dir LIMIT :limit OFFSET :offset");$bind=$p;$bind['status_now']=$now;foreach($bind as $k=>$v)$s->bindValue(':'.$k,$v);$s->bindValue(':limit',$c->pager->pageSize,PDO::PARAM_INT);$s->bindValue(':offset',($c->pager->page-1)*$c->pager->pageSize,PDO::PARAM_INT);$s->execute();$rows=$s->fetchAll(PDO::FETCH_ASSOC)?:[];foreach($rows as &$r){$decoded=json_decode((string)$r['scopes'],true);$r['scopes']=is_array($decoded)?implode(', ',array_filter($decoded,'is_string')):'';}return new PaginationResult($rows,(int)$n->fetchColumn(),$c->pager->page,$c->pager->pageSize);}}
